import itertools

def solve_small(n):
    tn = 2*n - 1
    min_size = float('inf')
    best_t = None

    # We need to choose n-1 elements from {1, 2, ..., tn-1}
    for t_mid in itertools.combinations(range(1, tn), n-1):
        t = [0] + list(t_mid) + [tn]
        s = set()
        for i in range(n+1):
            for j in range(i, n+1):
                s.add(t[i] + t[j])
        if len(s) < min_size:
            min_size = len(s)
            best_t = t
    return min_size, best_t

for n in range(1, 7):
    print(f"n={n}, min_size={solve_small(n)[0]}")

import itertools

def solve_small(n):
    tn = 2*n - 1
    min_size = float('inf')

    # For larger n, we can't use itertools.combinations.
    # Let's use a random search or a greedy approach.
    import random
    for _ in range(10000):
        t_mid = sorted(random.sample(range(1, tn), n-1))
        t = [0] + t_mid + [tn]
        s = set()
        for i in range(n+1):
            for j in range(i, n+1):
                s.add(t[i] + t[j])
        if len(s) < min_size:
            min_size = len(s)
    return min_size

for n in range(1, 11):
    print(f"n={n}, min_size={solve_small(n)}")

