    min_size = float('inf')
    for t_mid in itertools.combinations(range(1, tn), n-1):
        t = [0] + list(t_mid) + [tn]
        s = set()
        for i in range(n+1):
            for j in range(i, n+1):
                s.add(t[i] + t[j])
        if len(s) < min_size:
            min_size = len(s)
    return min_size

